const root = $input.first().json || {};
const execution = root.execution || {};
const error = execution.error || root.error || {};
const workflow = root.workflow || {};
const message = String(error.message || 'Error sin mensaje');
const lower = message.toLowerCase();
const severity = lower.includes('timeout') || lower.includes('connection') ? 'CRÍTICO' : 'Normal';
const nodeName = String((error.node && error.node.name) || execution.lastNodeExecuted || 'Nodo desconocido');
const workflowName = String(workflow.name || 'Workflow desconocido');
const executionUrl = String(execution.url || '');
const timestamp = DateTime.now().setZone('America/Caracas').toFormat('yyyy-MM-dd HH:mm:ss');
const esc = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const shown = message.length > 1500 ? `${message.slice(0, 1500)}…` : message;
const lines = [
  severity === 'CRÍTICO' ? '🔴 <b>Error crítico en n8n</b>' : '⚠️ <b>Error en n8n</b>',
  '',
  `<b>Cuándo:</b> ${esc(timestamp)}`,
  `<b>Workflow:</b> ${esc(workflowName)}`,
  `<b>Nodo:</b> ${esc(nodeName)}`,
  `<b>Tipo:</b> ${esc(severity)}`,
  `<b>Error:</b> ${esc(shown)}`,
];
if (executionUrl) lines.push('', `<a href="${esc(executionUrl)}">Ver ejecución</a>`);
return [{
  json: {
    timestamp,
    workflow_id: String(workflow.id || ''),
    workflow_name: workflowName,
    node_name: nodeName,
    error_message: message,
    severity,
    execution_id: String(execution.id || ''),
    execution_url: executionUrl,
    text: lines.join('\n'),
  },
}];
